int calls = 0; // статическая длительность хранения

void record() {
  int step = 1; // автоматическая длительность хранения
  calls += step;
}
// calls сохраняется между вызовами record().
// Для каждого вызова создаётся свой step, который уничтожается при возврате.

int copy_value(const int& value) {
  return value;
}

int prepare() {
  int reading = 18;
  return copy_value(reading);
}
// copy_value заимствует живой reading только на время вызова.
// prepare возвращает самостоятельный int, а не ссылку на reading.
